  v_link_ids uuid[] := ARRAY['1c2b3dd5-b137-5c0a-9600-efc19e743694'::uuid, '08d4a78f-b209-582c-b6dc-835288be4827'::uuid, '79ea500a-6ab0-5bdf-9195-cd1f2ae417ed'::uuid, 'd8746838-a96e-5c85-aa98-cb962781eff3'::uuid, '769a1b6d-6d9c-520d-98b0-f1ae87169af5'::uuid, '2998a798-6004-52d2-b0cc-e2bb1d299417'::uuid, 'eb7a83e4-a9f6-5577-bf38-7d92e60ea6ff'::uuid, 'fbf7ad26-7ae3-5760-82a6-be8cfb091bfc'::uuid, 'b2536692-5247-5653-9258-0a93cca0143d'::uuid, '37425695-867c-5402-89b5-65d58519de1e'::uuid, '9b9f0604-9dcb-566e-a9c6-37c071a9d38f'::uuid, '10ffc86b-118f-5d38-9ed7-2d65def16d50'::uuid, 'ba826c70-1971-5c76-b7a3-cd10b27e77ae'::uuid, '28512c63-1139-5f9e-9a24-7a7812374575'::uuid, '5be8f01e-ead7-5648-8190-e930c710ce6d'::uuid, '287686bf-1838-5473-8ae7-d21d012d0077'::uuid, '9f372c65-6c2b-5677-bc3f-822c3c3f2d94'::uuid, '509f10bf-330e-5731-b087-6409324f8c67'::uuid, 'f0142a96-4a2c-5ae2-9dba-e19ec598dc18'::uuid, 'f376f637-2141-5563-9f52-4e82392b0883'::uuid, '80484dd0-c304-56c4-9151-7929fd014791'::uuid, 'de64343d-c2a6-5cbb-be75-42bfda14cade'::uuid, 'b02885c6-05f6-57dd-a2b0-546ec5c9d06d'::uuid, '5b7d20fe-03fb-5df3-95fb-61390a0e0530'::uuid, 'b0f511a4-fc0d-5d10-8058-df2dfc1d87ad'::uuid, '16e67a24-b9bb-534a-912e-c07edeed77f8'::uuid, '5e71ecb1-8bcf-5fc9-bfda-222a7c6e6cca'::uuid, '0017189e-296b-5746-9e4d-00addda7b435'::uuid, 'f2dff67f-66cb-5da1-9393-8e0807484c5e'::uuid, '9e16def8-71e5-52e5-9efa-97624aab426d'::uuid, 'ec90000b-b3f4-5d76-9392-ed386a3d5cb3'::uuid]::uuid[];
  v_issue_ids uuid[] := ARRAY['7159d07f-c20d-59f6-b732-c498d054b208'::uuid, '87db6493-976b-5d03-8042-e1d8643c2f44'::uuid, '57ff4c1e-8e43-578f-99b8-f43770c4ae91'::uuid, 'd2a98e31-a3de-528f-a92a-a2b5ba82eb95'::uuid, '214c4661-c949-5671-a6db-3bdf6dd3bfdf'::uuid, '38b461e4-f125-59ab-8674-58638ffb8991'::uuid, 'c1ec4d76-88e6-50d3-a2ba-87a130d45efc'::uuid, 'b4a27f6e-daae-500d-87e6-8b125496101c'::uuid, '54fb6a6f-02e1-5fd9-a92c-6f8a4c80877a'::uuid, '44e197b3-007b-55c2-9fae-b84b41041fa2'::uuid]::uuid[];
  v_audit_ids uuid[] := ARRAY['aef21182-94c6-5e0d-95fd-fb51cd3e23f8'::uuid, '3336142b-eefa-55f1-b6db-22dd9574a1a5'::uuid, 'c0260501-0049-5283-a3bc-43972e300aa6'::uuid, 'ecd5fb57-c7e9-599c-9fcd-89f1c209d9aa'::uuid]::uuid[];
  v_count bigint;
BEGIN
  -- A. Preconditions: actual table contracts and exact runtime product set.
  IF to_regclass('public.catalog_source_documents') IS NULL
     OR to_regclass('public.catalog_source_evidence') IS NULL
     OR to_regclass('public.catalog_attribute_definitions') IS NULL
     OR to_regclass('public.catalog_attribute_values') IS NULL
     OR to_regclass('public.catalog_product_models') IS NULL
     OR to_regclass('public.catalog_product_content') IS NULL
     OR to_regclass('public.catalog_product_model_members') IS NULL
     OR to_regclass('public.catalog_asset_registry') IS NULL
     OR to_regclass('public.catalog_product_asset_links') IS NULL
     OR to_regclass('public.catalog_quality_issues') IS NULL
     OR to_regclass('public.catalog_approvals') IS NULL
     OR to_regclass('public.catalog_governance_state') IS NULL
     OR to_regclass('public.audit_events') IS NULL
  THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: required Governance table missing';
  END IF;

  IF jsonb_array_length(v_payload->'products') <> 30
     OR cardinality(v_product_ids) <> 30
     OR (SELECT count(DISTINCT x) FROM unnest(v_product_ids) AS t(x)) <> 30
  THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: pilot payload is not exactly 30 products';
  END IF;

  SELECT count(*) INTO v_count
  FROM public.productos_b2b
  WHERE id = ANY(v_product_ids);
  IF v_count <> 30 THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: one or more runtime product IDs are absent';
  END IF;

  -- B. Conflict guards. Same deterministic ID must be content-equivalent.
  IF EXISTS (
    SELECT 1
    FROM public.catalog_governance_state s
    JOIN jsonb_to_recordset(v_payload->'governance_state') AS r(
      id uuid, producto_b2b_id uuid, identity_status text, data_status text,
      content_status text, image_status text, review_status text
    ) ON r.id = s.id
    WHERE s.producto_b2b_id IS DISTINCT FROM r.producto_b2b_id
       OR s.identity_status IS DISTINCT FROM r.identity_status
       OR s.data_status IS DISTINCT FROM r.data_status
       OR s.content_status IS DISTINCT FROM r.content_status
       OR s.image_status IS DISTINCT FROM r.image_status
       OR s.review_status IS DISTINCT FROM r.review_status
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: governance state deterministic-ID collision';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_product_content c
    JOIN jsonb_to_recordset(v_payload->'content') AS r(
      id uuid, producto_b2b_id uuid, version integer, is_current boolean,
      canonical_name text, short_description text, structured_features jsonb,
      technical_specifications jsonb, available_colors jsonb, status text
    ) ON r.id = c.id
    WHERE c.producto_b2b_id IS DISTINCT FROM r.producto_b2b_id
       OR c.version IS DISTINCT FROM r.version
       OR c.is_current IS DISTINCT FROM r.is_current
       OR c.canonical_name IS DISTINCT FROM r.canonical_name
       OR c.short_description IS DISTINCT FROM r.short_description
       OR c.structured_features IS DISTINCT FROM r.structured_features
       OR c.technical_specifications IS DISTINCT FROM r.technical_specifications
       OR c.available_colors IS DISTINCT FROM r.available_colors
       OR c.status IS DISTINCT FROM r.status
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: content deterministic-ID collision';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_asset_registry a
    JOIN jsonb_to_recordset(v_payload->'assets') AS r(
      id uuid, source_document_id uuid, source_uri text, original_filename text,
      sha256 text, file_size_bytes bigint, mime_type text, width integer, height integer,
      rights_status text, identity_status text, technical_status text, visual_status text,
      approval_status text, public_url text, version integer, metadata jsonb
    ) ON r.id = a.id
    WHERE a.source_document_id IS DISTINCT FROM r.source_document_id
       OR a.source_uri IS DISTINCT FROM r.source_uri
       OR a.original_filename IS DISTINCT FROM r.original_filename
       OR a.sha256 IS DISTINCT FROM r.sha256
       OR a.file_size_bytes IS DISTINCT FROM r.file_size_bytes
       OR a.mime_type IS DISTINCT FROM r.mime_type
       OR a.width IS DISTINCT FROM r.width
       OR a.height IS DISTINCT FROM r.height
       OR a.rights_status IS DISTINCT FROM r.rights_status
       OR a.identity_status IS DISTINCT FROM r.identity_status
       OR a.technical_status IS DISTINCT FROM r.technical_status
       OR a.visual_status IS DISTINCT FROM r.visual_status
       OR a.approval_status IS DISTINCT FROM r.approval_status
       OR a.public_url IS DISTINCT FROM r.public_url
       OR a.version IS DISTINCT FROM r.version
       OR a.metadata IS DISTINCT FROM r.metadata
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: asset deterministic-ID collision';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_product_asset_links l
    JOIN jsonb_to_recordset(v_payload->'asset_links') AS r(
      id uuid, asset_id uuid, target_type text, producto_b2b_id uuid,
      role text, display_order integer, link_status text, evidence_id uuid
    ) ON r.id = l.id
    WHERE l.asset_id IS DISTINCT FROM r.asset_id
       OR l.target_type IS DISTINCT FROM r.target_type
       OR l.producto_b2b_id IS DISTINCT FROM r.producto_b2b_id
       OR l.role IS DISTINCT FROM r.role
       OR l.display_order IS DISTINCT FROM r.display_order
       OR l.link_status IS DISTINCT FROM r.link_status
       OR l.evidence_id IS DISTINCT FROM r.evidence_id
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: asset-link deterministic-ID collision';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_quality_issues q
    JOIN jsonb_to_recordset(v_payload->'quality_issues') AS r(
      id uuid, issue_code text, severity text, subject_type text, subject_id uuid,
      status text, source_evidence_id uuid, details jsonb
    ) ON r.id = q.id
    WHERE q.issue_code IS DISTINCT FROM r.issue_code
       OR q.severity IS DISTINCT FROM r.severity
       OR q.subject_type IS DISTINCT FROM r.subject_type
       OR q.subject_id IS DISTINCT FROM r.subject_id
       OR q.status IS DISTINCT FROM r.status
       OR q.source_evidence_id IS DISTINCT FROM r.source_evidence_id
       OR q.details IS DISTINCT FROM r.details
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: quality-issue deterministic-ID collision';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_source_documents d
    JOIN jsonb_to_recordset(v_payload->'source_documents') AS r(
      id uuid, source_type text, source_uri text, original_filename text,
      sha256 text, rights_status text, metadata jsonb
    ) ON r.id = d.id
    WHERE d.source_type IS DISTINCT FROM r.source_type
       OR d.source_uri IS DISTINCT FROM r.source_uri
       OR d.original_filename IS DISTINCT FROM r.original_filename
       OR d.sha256 IS DISTINCT FROM r.sha256
       OR d.rights_status IS DISTINCT FROM r.rights_status
       OR d.metadata IS DISTINCT FROM r.metadata
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: source-document deterministic-ID collision';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_source_evidence e
    JOIN jsonb_to_recordset(v_payload->'product_evidence' || v_payload->'asset_evidence') AS r(
      id uuid, source_document_id uuid, subject_type text, subject_id uuid,
      field_path text, raw_value text, evidence_excerpt text, confidence numeric,
      status text
    ) ON r.id = e.id
    WHERE e.source_document_id IS DISTINCT FROM r.source_document_id
       OR e.subject_type IS DISTINCT FROM r.subject_type
       OR e.subject_id IS DISTINCT FROM r.subject_id
       OR e.field_path IS DISTINCT FROM r.field_path
       OR e.raw_value IS DISTINCT FROM r.raw_value
       OR e.evidence_excerpt IS DISTINCT FROM r.evidence_excerpt
       OR e.confidence IS DISTINCT FROM r.confidence
       OR e.status IS DISTINCT FROM r.status
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: source-evidence deterministic-ID collision';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.audit_events a
    JOIN jsonb_to_recordset(v_payload->'audit_events') AS r(
      id uuid, actor_type text, action text, entity_type text, entity_id uuid,
      checkpoint text, metadata jsonb
    ) ON r.id = a.id
    WHERE a.actor_type IS DISTINCT FROM r.actor_type
       OR a.action IS DISTINCT FROM r.action
       OR a.entity_type IS DISTINCT FROM r.entity_type
       OR a.entity_id IS DISTINCT FROM r.entity_id
       OR a.checkpoint IS DISTINCT FROM r.checkpoint
       OR a.metadata IS DISTINCT FROM r.metadata
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: audit-event deterministic-ID collision';
  END IF;

  -- Semantic guards stop ambiguous pre-existing Governance data.
  IF EXISTS (
    SELECT 1 FROM public.catalog_governance_state
    WHERE producto_b2b_id = ANY(v_product_ids) AND id <> ALL(v_state_ids)
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: pre-existing Governance state collision';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.catalog_product_content
    WHERE producto_b2b_id = ANY(v_product_ids) AND id <> ALL(v_content_ids)
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: pre-existing content collision';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.catalog_attribute_values
    WHERE subject_type = 'PRODUCT' AND subject_id = ANY(v_product_ids)
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: pre-existing attribute data for pilot scope';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.catalog_product_model_members
    WHERE producto_b2b_id = ANY(v_product_ids)
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: pre-existing model membership for pilot scope';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.catalog_approvals
    WHERE subject_id = ANY(v_product_ids)
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: pre-existing approval for pilot scope';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.catalog_product_models
    WHERE model_key IN ('G4_LOBBY','G4_JELLO_COLORS_BIO','G4_JELLO_ZEN','G4_VASO_NOMI','G4_SPLASH')
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: candidate model key already exists';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.catalog_source_documents d
    JOIN jsonb_to_recordset(v_payload->'source_documents') AS r(
      id uuid, source_uri text, sha256 text
    ) ON (d.source_uri = r.source_uri OR d.sha256 = r.sha256)
    WHERE d.id <> r.id
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: source-document semantic collision';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.catalog_asset_registry a
    JOIN jsonb_to_recordset(v_payload->'assets') AS r(
      id uuid, source_document_id uuid, source_uri text, sha256 text
    ) ON (a.source_uri = r.source_uri OR a.sha256 = r.sha256)
    WHERE a.id <> r.id
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: asset semantic collision';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.catalog_source_evidence e
    JOIN (SELECT * FROM jsonb_to_recordset(v_payload->'product_evidence' || v_payload->'asset_evidence') AS z(
      id uuid, source_document_id uuid, subject_type text, subject_id uuid, field_path text
    )) r ON e.source_document_id = r.source_document_id
        AND e.subject_type = r.subject_type
        AND e.subject_id = r.subject_id
        AND e.field_path IS NOT DISTINCT FROM r.field_path
    WHERE e.id <> r.id
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: evidence semantic collision';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.catalog_quality_issues q
    JOIN jsonb_to_recordset(v_payload->'quality_issues') AS r(
      id uuid, subject_type text, subject_id uuid, issue_code text
    ) ON q.subject_type = r.subject_type AND q.subject_id = r.subject_id AND q.issue_code = r.issue_code
    WHERE q.id <> r.id AND q.status IN ('OPEN','IN_REVIEW')
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: active issue semantic collision';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.catalog_product_asset_links l
    JOIN jsonb_to_recordset(v_payload->'asset_links') AS r(
      id uuid, asset_id uuid, target_type text, producto_b2b_id uuid, role text
    ) ON l.asset_id = r.asset_id
       AND l.target_type = r.target_type
       AND l.producto_b2b_id = r.producto_b2b_id
       AND l.role = r.role
    WHERE l.id <> r.id
  ) THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: asset-link semantic collision';
  END IF;

  -- C. Source document inserts.
  INSERT INTO public.catalog_source_documents
    (id, source_type, source_uri, original_filename, sha256, rights_status, metadata)
  SELECT r.id, r.source_type, r.source_uri, r.original_filename, r.sha256, r.rights_status, r.metadata
  FROM jsonb_to_recordset(v_payload->'source_documents') AS r(
    id uuid, source_type text, source_uri text, original_filename text,
    sha256 text, rights_status text, metadata jsonb
  )
  ON CONFLICT DO NOTHING;

  -- D. Source evidence inserts.
  INSERT INTO public.catalog_source_evidence
    (id, source_document_id, subject_type, subject_id, field_path, raw_value,
     evidence_excerpt, confidence, status)
  SELECT r.id, r.source_document_id, r.subject_type, r.subject_id, r.field_path,
         r.raw_value, r.evidence_excerpt, r.confidence, r.status
  FROM jsonb_to_recordset(v_payload->'product_evidence' || v_payload->'asset_evidence') AS r(
    id uuid, source_document_id uuid, subject_type text, subject_id uuid,
    field_path text, raw_value text, evidence_excerpt text, confidence numeric, status text
  )
  ON CONFLICT DO NOTHING;

  -- E/F. No attribute definitions or values are planned or inserted (0/0).

  -- G. Content inserts.
  INSERT INTO public.catalog_product_content
    (id, producto_b2b_id, version, is_current, canonical_name, short_description,
     structured_features, technical_specifications, available_colors, status)
  SELECT r.id, r.producto_b2b_id, r.version, r.is_current, r.canonical_name,
         r.short_description, r.structured_features, r.technical_specifications,
         r.available_colors, r.status
  FROM jsonb_to_recordset(v_payload->'content') AS r(
    id uuid, producto_b2b_id uuid, version integer, is_current boolean,
    canonical_name text, short_description text, structured_features jsonb,
    technical_specifications jsonb, available_colors jsonb, status text
  )
  ON CONFLICT DO NOTHING;

  -- H. Asset registry inserts.
  INSERT INTO public.catalog_asset_registry
    (id, source_document_id, source_uri, original_filename, sha256, file_size_bytes,
     mime_type, width, height, rights_status, identity_status, technical_status,
     visual_status, approval_status, public_url, version, metadata)
  SELECT r.id, r.source_document_id, r.source_uri, r.original_filename, r.sha256,
         r.file_size_bytes, r.mime_type, r.width, r.height, r.rights_status,
         r.identity_status, r.technical_status, r.visual_status, r.approval_status,
         r.public_url, r.version, r.metadata
  FROM jsonb_to_recordset(v_payload->'assets') AS r(
    id uuid, source_document_id uuid, source_uri text, original_filename text,
    sha256 text, file_size_bytes bigint, mime_type text, width integer, height integer,
    rights_status text, identity_status text, technical_status text, visual_status text,
    approval_status text, public_url text, version integer, metadata jsonb
  )
  ON CONFLICT DO NOTHING;

  -- I. Asset link inserts.
  INSERT INTO public.catalog_product_asset_links
    (id, asset_id, target_type, model_id, producto_b2b_id, oferta_id, role,
     display_order, link_status, evidence_id)
  SELECT r.id, r.asset_id, r.target_type, NULL::uuid, r.producto_b2b_id,
         NULL::uuid, r.role, r.display_order, r.link_status, r.evidence_id
  FROM jsonb_to_recordset(v_payload->'asset_links') AS r(
    id uuid, asset_id uuid, target_type text, producto_b2b_id uuid, role text,
    display_order integer, link_status text, evidence_id uuid
  )
  ON CONFLICT DO NOTHING;

  -- J. Quality issue inserts.
  INSERT INTO public.catalog_quality_issues
    (id, issue_code, severity, subject_type, subject_id, status,
     source_evidence_id, details)
  SELECT r.id, r.issue_code, r.severity, r.subject_type, r.subject_id, r.status,
         r.source_evidence_id, r.details
  FROM jsonb_to_recordset(v_payload->'quality_issues') AS r(
    id uuid, issue_code text, severity text, subject_type text, subject_id uuid,
    status text, source_evidence_id uuid, details jsonb
  )
  ON CONFLICT DO NOTHING;

  -- K. Governance state inserts.
  INSERT INTO public.catalog_governance_state
    (id, producto_b2b_id, identity_status, data_status, content_status,
     image_status, review_status)
  SELECT r.id, r.producto_b2b_id, r.identity_status, r.data_status, r.content_status,
         r.image_status, r.review_status
  FROM jsonb_to_recordset(v_payload->'governance_state') AS r(
    id uuid, producto_b2b_id uuid, identity_status text, data_status text,
    content_status text, image_status text, review_status text
  )
  ON CONFLICT DO NOTHING;

  -- L. Audit event inserts.
  INSERT INTO public.audit_events
    (id, actor_type, action, entity_type, entity_id, checkpoint, metadata)
  SELECT r.id, r.actor_type, r.action, r.entity_type, r.entity_id, r.checkpoint, r.metadata
  FROM jsonb_to_recordset(v_payload->'audit_events') AS r(
    id uuid, actor_type text, action text, entity_type text, entity_id uuid,
    checkpoint text, metadata jsonb
  )
  ON CONFLICT DO NOTHING;

  -- M. Post-insert assertions.
  IF (SELECT count(*) FROM public.catalog_source_documents WHERE id = ANY(v_document_ids)) <> 2
     OR (SELECT count(*) FROM public.catalog_source_evidence WHERE id = ANY(v_evidence_ids)) <> 61
     OR (SELECT count(*) FROM public.catalog_product_content WHERE id = ANY(v_content_ids)) <> 30
     OR (SELECT count(*) FROM public.catalog_asset_registry WHERE id = ANY(v_asset_ids)) <> 31
     OR (SELECT count(*) FROM public.catalog_product_asset_links WHERE id = ANY(v_link_ids)) <> 31
     OR (SELECT count(*) FROM public.catalog_quality_issues WHERE id = ANY(v_issue_ids)) <> 10
     OR (SELECT count(*) FROM public.catalog_governance_state WHERE id = ANY(v_state_ids)) <> 30
     OR (SELECT count(*) FROM public.audit_events WHERE id = ANY(v_audit_ids)) <> 4
  THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: post-insert count assertion failed';
  END IF;

  IF (SELECT count(*) FROM public.catalog_governance_state
      WHERE id = ANY(v_state_ids) AND identity_status = 'NEEDS_REVIEW') <> 20
     OR (SELECT count(*) FROM public.catalog_governance_state
         WHERE id = ANY(v_state_ids) AND identity_status = 'BLOCKED') <> 10
     OR EXISTS (SELECT 1 FROM public.catalog_attribute_values WHERE subject_id = ANY(v_product_ids))
     OR EXISTS (SELECT 1 FROM public.catalog_product_model_members WHERE producto_b2b_id = ANY(v_product_ids))
     OR EXISTS (SELECT 1 FROM public.catalog_approvals WHERE subject_id = ANY(v_product_ids))
  THEN
    RAISE EXCEPTION 'CHK-CATGOV-03E: negative row assertion failed';
  END IF;
END
$g4_apply$;

COMMIT;
